<template>
  <section class="team" v-loading="loading">
    <header><div><small>SEO AI WORKSPACE</small><h2>团队与权限</h2><p>{{ organization?.name || '当前工作区' }} 的成员管理。</p></div><div><el-button v-if="canManage" type="primary" @click="inviteOpen=true"><i class="fas fa-user-plus"/> 邀请成员</el-button><el-button @click="load"><i class="fas fa-refresh"/> 刷新</el-button></div></header>
    <div class="summary"><b>{{ members.length }}</b><span>组织成员</span><em>当前角色：{{ roles[organization?.role] || '-' }}</em></div>
    <el-table :data="members" stripe><el-table-column label="成员" min-width="220"><template #default="{row}"><div class="member"><img v-if="row.avatar" :src="row.avatar" alt=""><span>{{ row.display_name || row.username || row.email }}</span></div></template></el-table-column><el-table-column prop="email" label="邮箱" min-width="190"/><el-table-column label="角色" width="150"><template #default="{row}"><el-select v-if="canManage && row.role !== 'owner'" v-model="row.role" size="small" @change="updateRole(row)"><el-option v-for="(label,value) in editableRoles" :key="value" :label="label" :value="value"/></el-select><el-tag v-else size="small">{{ roles[row.role] || row.role }}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag size="small" :type="row.status==='active'?'success':'info'">{{ row.status==='active'?'启用':row.status==='invited'?'待加入':'停用' }}</el-tag></template></el-table-column><el-table-column prop="created_at" label="加入时间" min-width="170"/></el-table>
    <el-dialog v-model="inviteOpen" title="邀请成员" width="430px"><el-form label-position="top"><el-form-item label="注册邮箱"><el-input v-model="invite.email" placeholder="name@example.com"/></el-form-item><el-form-item label="角色"><el-select v-model="invite.role" style="width:100%"><el-option v-for="(label,value) in editableRoles" :key="value" :label="label" :value="value"/></el-select></el-form-item></el-form><template #footer><el-button @click="inviteOpen=false">取消</el-button><el-button type="primary" :loading="inviting" @click="sendInvite">发送邀请</el-button></template></el-dialog>
  </section>
</template>
<script setup>
import { ref, computed, onMounted, reactive } from 'vue'; import api from '@/api'; import { ElMessage } from 'element-plus'
const loading=ref(false),members=ref([]),organization=ref(null),inviteOpen=ref(false),inviting=ref(false),invite=reactive({email:'',role:'viewer'}),roles={owner:'所有者',admin:'管理员',seo:'SEO',editor:'编辑',reviewer:'审核者',viewer:'只读'},editableRoles={admin:'管理员',seo:'SEO',editor:'编辑',reviewer:'审核者',viewer:'只读'},canManage=computed(()=>['owner','admin'].includes(organization.value?.role))
async function load(){loading.value=true;try{const r=await api.get('/user/membership/members');organization.value=r.data?.organization;members.value=r.data?.members||[]}finally{loading.value=false}}
async function updateRole(row){try{await api.put(`/user/membership/members/${row.id}/role`,{role:row.role});ElMessage.success('成员角色已更新')}catch{load()}}
async function sendInvite(){if(!invite.email.trim())return ElMessage.warning('请输入邮箱');inviting.value=true;try{await api.post('/user/membership/members/invite',invite);ElMessage.success('邀请已创建');inviteOpen.value=false;invite.email='';await load()}finally{inviting.value=false}}
onMounted(load)
</script>
<style scoped>.team{max-width:1180px;margin:auto}.team header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.team small{color:#1677ff;font-weight:700}.team h2{font-size:24px;margin:5px 0}.team p{color:#667085;margin:0}.summary{display:flex;align-items:baseline;gap:10px;background:#fff;border:1px solid #e4e8ee;border-radius:7px;padding:16px;margin-bottom:14px}.summary b{font-size:28px}.summary span,.summary em{color:#667085;font-size:12px}.summary em{margin-left:auto;font-style:normal}.member{display:flex;align-items:center;gap:9px}.member img{width:28px;height:28px;border-radius:50%;object-fit:cover}@media(max-width:700px){.team p{display:none}.summary em{display:none}}
</style>
